      proxyDiagnostics: null,
      preferBatchLoad: true,
      reloadDirtyChunksAfterCommand: true,
      maxBatchChunks: DEFAULT_CHUNK_SERVICE_MAX_BATCH_CHUNKS,
      routeHints,
      timeouts: DEFAULT_CHUNK_SERVICE_TIMEOUTS
