    mode: DEFAULT_EDITOR_RUNTIME_MODE,
    worldMode: DEFAULT_EDITOR_WORLD_MODE,
    sourceMode: DEFAULT_EDITOR_WORLD_SOURCE_MODE,
    localWorldFallbackEnabled: false,
    legacyFrontendEnabled: false,
